#include <bits/stdc++.h>
using namespace std;

int first_at_least(const vector<long long>& values, long long target) {
    int n = values.size();
    int low = 0;
    int high = n;

while (low < high) {
    int middle = low + (high - low) / 2;

    if (values[middle] >= target) {
        high = middle;
    } else {
        low = middle + 1;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> values(n);
    for (int i = 0; i < n; i++) {
        cin >> values[i];
    }
    int queryCount;
    cin >> queryCount;
    for (int i = 0; i < queryCount; i++) {
        long long target;
        cin >> target;
        cout << first_at_least(values, target) << '\n';
    }

    return 0;
}

